class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        C = [[0]*(L+1) for _ in range(L+1)]
        for i in range(L+1):
            C[i][0] = 1
            for j in range(1, i+1):
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD
        st = [0]*(L+1)
        for c in range(2, L+1):
            st[c] = 1 + st[bin(c).count('1')]
        ok = [c for c in range(1, L+1) if st[c] <= k-1]
        ans = 0
        ones = 0
        for i, ch in enumerate(s):
            rem = L - i - 1
            if ch == '1':
                for need in ok:
                    if need >= ones:
                        ans = (ans + C[rem][need-ones]) % MOD
                ones += 1
        return ans

