class Solution {
public:
    int countKReducibleNumbers(string s, int k) {
        const long long MOD = 1e9 + 7;
        int L = s.size();
        vector<vector<long long>> C(L+1, vector<long long>(L+1, 0));
        for (int i = 0; i <= L; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++)
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD;
        }
        vector<int> st(L+1, 0);
        for (int c = 2; c <= L; c++)
            st[c] = 1 + st[__builtin_popcount(c)];
        vector<int> ok;
        for (int c = 1; c <= L; c++)
            if (st[c] <= k-1) ok.push_back(c);
        long long ans = 0;
        int ones = 0;
        for (int i = 0; i < L; i++) {
            int rem = L - i - 1;
            if (s[i] == '1') {
                for (int need : ok)
                    if (need >= ones)
                        ans = (ans + C[rem][need-ones]) % MOD;
                ones++;
            }
        }
        return (int)ans;
    }
};

