class Solution {
    public int countKReducibleNumbers(String s, int k) {
        final long MOD = 1_000_000_007L;
        int L = s.length();
        long[][] C = new long[L+1][L+1];
        for (int i = 0; i <= L; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++)
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD;
        }
        int[] st = new int[L+1];
        for (int c = 2; c <= L; c++)
            st[c] = 1 + st[Integer.bitCount(c)];
        List<Integer> ok = new ArrayList<>();
        for (int c = 1; c <= L; c++)
            if (st[c] <= k-1) ok.add(c);
        long ans = 0;
        int ones = 0;
        for (int i = 0; i < L; i++) {
            int rem = L - i - 1;
            if (s.charAt(i) == '1') {
                for (int need : ok)
                    if (need >= ones)
                        ans = (ans + C[rem][need-ones]) % MOD;
                ones++;
            }
        }
        return (int)ans;
    }
}

