var countKReducibleNumbers = function(s, k) {
    const MOD = 1e9 + 7;
    const L = s.length;
    const C = Array.from({length: L+1}, () => new Array(L+1).fill(0));
    for (let i = 0; i <= L; i++) {
        C[i][0] = 1;
        for (let j = 1; j <= i; j++)
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD;
    }
    const bc = (x) => { let c = 0; while (x) { c += x & 1; x >>= 1; } return c; };
    const st = new Array(L+1).fill(0);
    for (let c = 2; c <= L; c++) st[c] = 1 + st[bc(c)];
    const ok = [];
    for (let c = 1; c <= L; c++) if (st[c] <= k-1) ok.push(c);
    let ans = 0, ones = 0;
    for (let i = 0; i < L; i++) {
        const rem = L - i - 1;
        if (s[i] === '1') {
            for (const need of ok)
                if (need >= ones) ans = (ans + C[rem][need-ones]) % MOD;
            ones++;
        }
    }
    return ans;
};
